// NEMA11 toolchain correction: exact finite-segment/circle clearance.
      // Keep the original clearance threshold and every diagnostic in force.
      const gap = obj.type === "pcb_keepout" && obj.shape === "circle"
        ? (() => {
            const dx = segmentA.x2 - segmentA.x1;
            const dy = segmentA.y2 - segmentA.y1;
            const lengthSquared = dx * dx + dy * dy;
            const t = lengthSquared === 0 ? 0 : Math.max(0, Math.min(1,
              ((obj.center.x - segmentA.x1) * dx + (obj.center.y - segmentA.y1) * dy) / lengthSquared));
            return Math.hypot(obj.center.x - segmentA.x1 - t * dx,
              obj.center.y - segmentA.y1 - t * dy) - obj.radius - segmentA.thickness / 2;
          })()
        : segmentToBoundsMinDistance(
        { x: segmentA.x1, y: segmentA.y1 },
        { x: segmentA.x2, y: segmentA.y2 },
        getCollidableBounds(obj)
      ) - segmentA.thickness / 2;

